-- Initial schema for Clarity.
--
-- Generated from supabase/schemas/*.sql (the source of truth), in file order.
-- Do not edit this file after it has been applied anywhere: change the schema
-- files and create a NEW migration for the change.


-- ════════════════════════════════════════════════════════════════════════════
-- schemas/00_foundation.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Foundation: extensions, enum types, the private helper schema and shared
-- trigger functions. Every later schema file builds on these.
--
-- Conventions used by every schema file in this folder:
--   * Tables live in `public` and are reached through the Data API.
--   * Row-level security is enabled on every table, with explicit policies.
--   * New tables are NOT auto-exposed, so each file grants exactly the
--     privileges the app needs to `authenticated` (and never more to `anon`).
--   * Security-definer helpers live in `private`, which the Data API does not
--     expose, so they can be used by policies but not called over HTTP.

create extension if not exists postgis with schema extensions;
create extension if not exists citext with schema extensions;

-- ── Enum types ──────────────────────────────────────────────────────────────

create type public.place_category as enum (
  'food', 'cafe', 'stay', 'trek', 'viewpoint', 'temple', 'beach', 'shop', 'other'
);

create type public.visit_status as enum ('visited', 'want_to_go', 'not_recommended');

create type public.profile_visibility as enum ('public', 'friends', 'private');

create type public.friendship_status as enum ('pending', 'accepted');

create type public.list_role as enum ('owner', 'editor');

create type public.like_subject as enum ('visit', 'ask', 'list');

create type public.notification_kind as enum (
  'joined', 'friend_request', 'liked', 'thanks', 'nudge', 'list_invite'
);

-- ── Private schema for helpers ──────────────────────────────────────────────

create schema if not exists private;

revoke all on schema private from public;
grant usage on schema private to authenticated, service_role;

-- ── Shared triggers ─────────────────────────────────────────────────────────

-- Keeps `updated_at` current on every UPDATE.
create function private.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;


-- ════════════════════════════════════════════════════════════════════════════
-- schemas/01_profiles.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Profiles: the public identity of a signed-in user.
--
-- Authentication itself is Supabase Auth (`auth.users`, phone OTP via Twilio).
-- The verified phone number stays in `auth.users.phone` and is never copied
-- here or exposed through the Data API.

create table public.profiles (
  id                    uuid primary key references auth.users (id) on delete cascade,
  username              extensions.citext not null unique
                          check (username::text ~ '^[a-z0-9._]{3,30}$'),
  display_name          text not null check (char_length(display_name) between 1 and 60),
  home_city             text check (char_length(home_city) <= 60),
  -- Initials-avatar tint, stable per person (design system: Avatar).
  avatar_bg             text not null default '#DDEAFB' check (avatar_bg ~ '^#[0-9A-Fa-f]{6}$'),
  avatar_fg             text not null default '#1D4E9E' check (avatar_fg ~ '^#[0-9A-Fa-f]{6}$'),
  avatar_path           text,
  -- Who can see this person's visits (PRD PRV-1). Identity is always visible
  -- to signed-in users so requests, search and contact matches work.
  visibility            public.profile_visibility not null default 'friends',
  -- "Let people who have my number find me" (PRD CON-8).
  discoverable_by_phone boolean not null default true,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now()
);

comment on table public.profiles is 'Public identity of each user; one row per auth.users row.';

create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function private.set_updated_at();

-- ── Row-level security ──────────────────────────────────────────────────────

alter table public.profiles enable row level security;

create policy "Signed-in users can read profiles"
  on public.profiles for select
  to authenticated
  using (true);

create policy "Users create their own profile"
  on public.profiles for insert
  to authenticated
  with check (id = (select auth.uid()));

create policy "Users update their own profile"
  on public.profiles for update
  to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

-- ── Grants ──────────────────────────────────────────────────────────────────

grant select, insert, update on public.profiles to authenticated;
grant all on public.profiles to service_role;

-- ── Functions ───────────────────────────────────────────────────────────────

-- Create-profile screen: is this username free? (Case-insensitive.)
create function public.is_username_available(candidate text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select candidate ~ '^[a-z0-9._]{3,30}$'
     and not exists (
       select 1 from public.profiles p
       where p.username = candidate::extensions.citext
         and p.id <> (select auth.uid())
     );
$$;

revoke execute on function public.is_username_available(text) from public, anon;
grant execute on function public.is_username_available(text) to authenticated;


-- ════════════════════════════════════════════════════════════════════════════
-- schemas/02_friendships.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Friendships: mutual connections. A row is a request until the addressee
-- accepts it. One row per pair, whichever direction it was sent in.

create table public.friendships (
  requester_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  addressee_id uuid not null references public.profiles (id) on delete cascade,
  status       public.friendship_status not null default 'pending',
  created_at   timestamptz not null default now(),
  responded_at timestamptz,
  primary key (requester_id, addressee_id),
  check (requester_id <> addressee_id)
);

comment on table public.friendships is 'Friend requests (pending) and friendships (accepted).';

-- Only one row per pair, regardless of who asked.
create unique index friendships_pair_key
  on public.friendships (least(requester_id, addressee_id), greatest(requester_id, addressee_id));

create index friendships_addressee_idx on public.friendships (addressee_id, status);

-- Stamp the time a request was accepted.
create function private.stamp_friendship_response()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'accepted' and old.status = 'pending' then
    new.responded_at := now();
  end if;
  return new;
end;
$$;

create trigger friendships_stamp_response
  before update on public.friendships
  for each row execute function private.stamp_friendship_response();

-- ── Helpers used by policies everywhere ─────────────────────────────────────

-- True when a and b are accepted friends.
create function private.are_friends(a uuid, b uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.friendships f
    where f.status = 'accepted'
      and ((f.requester_id = a and f.addressee_id = b)
        or (f.requester_id = b and f.addressee_id = a))
  );
$$;

-- The caller's accepted friends.
create function private.friend_ids()
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select case when f.requester_id = (select auth.uid()) then f.addressee_id else f.requester_id end
  from public.friendships f
  where f.status = 'accepted'
    and (select auth.uid()) in (f.requester_id, f.addressee_id);
$$;

-- Can the caller see `owner`'s visits, lists and stats? (PRD PRV-1)
--   public  → every signed-in user
--   friends → accepted friends
--   private → only the owner
create function private.can_view_profile(owner uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select owner = (select auth.uid())
      or exists (
        select 1 from public.profiles p
        where p.id = owner
          and (p.visibility = 'public'
            or (p.visibility = 'friends' and private.are_friends((select auth.uid()), owner)))
      );
$$;

revoke execute on all functions in schema private from public, anon;
grant execute on function private.are_friends(uuid, uuid) to authenticated;
grant execute on function private.friend_ids() to authenticated;
grant execute on function private.can_view_profile(uuid) to authenticated;

-- ── Row-level security ──────────────────────────────────────────────────────

alter table public.friendships enable row level security;

create policy "Either side can see the friendship"
  on public.friendships for select
  to authenticated
  using ((select auth.uid()) in (requester_id, addressee_id));

create policy "Users send requests as themselves"
  on public.friendships for insert
  to authenticated
  with check (requester_id = (select auth.uid()) and status = 'pending');

create policy "The addressee accepts a request"
  on public.friendships for update
  to authenticated
  using (addressee_id = (select auth.uid()) and status = 'pending')
  with check (addressee_id = (select auth.uid()) and status = 'accepted');

-- Decline, cancel and unfriend are all deletes.
create policy "Either side can remove the friendship"
  on public.friendships for delete
  to authenticated
  using ((select auth.uid()) in (requester_id, addressee_id));

-- ── Grants ──────────────────────────────────────────────────────────────────

grant select, insert, delete on public.friendships to authenticated;
grant update (status) on public.friendships to authenticated;
grant all on public.friendships to service_role;


-- ════════════════════════════════════════════════════════════════════════════
-- schemas/03_places.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Places: real-world locations, shared by everyone. A place never holds an
-- opinion — ratings and reviews live in `visits`.

create table public.places (
  id              uuid primary key default gen_random_uuid(),
  -- Google Places (New) id; null for pins dropped by hand.
  google_place_id text unique,
  name            text not null check (char_length(name) between 1 and 120),
  category        public.place_category not null,
  lat             double precision not null check (lat between -90 and 90),
  lng             double precision not null check (lng between -180 and 180),
  -- Derived from lat/lng for PostGIS queries ("within 2 km", clustering).
  location        extensions.geography(point, 4326)
                    generated always as (
                      extensions.st_setsrid(extensions.st_makepoint(lng, lat), 4326)::extensions.geography
                    ) stored,
  -- Short locality for meta lines ("Melaghar") and the longer address.
  area            text not null default '' check (char_length(area) <= 80),
  address         text not null default '' check (char_length(address) <= 200),
  city            text check (char_length(city) <= 80),
  country_code    char(2) not null default 'IN',
  created_by      uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

comment on table public.places is 'Shared, opinion-free places. Deduplicated by google_place_id.';

create index places_location_idx on public.places using gist (location);
create index places_name_idx on public.places (lower(name) text_pattern_ops);

create trigger places_set_updated_at
  before update on public.places
  for each row execute function private.set_updated_at();

-- ── Row-level security ──────────────────────────────────────────────────────

alter table public.places enable row level security;

create policy "Signed-in users can read places"
  on public.places for select
  to authenticated
  using (true);

create policy "Signed-in users add places as themselves"
  on public.places for insert
  to authenticated
  with check (created_by = (select auth.uid()));

-- Only dropped pins (no Google id) can be edited, and only by their creator.
create policy "Creators edit their dropped pins"
  on public.places for update
  to authenticated
  using (created_by = (select auth.uid()) and google_place_id is null)
  with check (created_by = (select auth.uid()) and google_place_id is null);

-- ── Grants ──────────────────────────────────────────────────────────────────

grant select on public.places to authenticated;
-- `id` is allowed so the app can create a pin optimistically with its own UUID.
grant insert (id, google_place_id, name, category, lat, lng, area, address, city, country_code)
  on public.places to authenticated;
grant update (name, category, lat, lng, area, address, city) on public.places to authenticated;
grant all on public.places to service_role;

-- ── Functions ───────────────────────────────────────────────────────────────

-- "I'm here": places within `radius_m` of a point, nearest first.
-- Parameters are prefixed so they can't be confused with the lat/lng columns.
create function public.nearby_places(at_lat double precision, at_lng double precision, radius_m integer default 2000)
returns table (place_id uuid, distance_m double precision)
language sql
stable
set search_path = ''
as $$
  select p.id,
         extensions.st_distance(
           p.location,
           extensions.st_setsrid(extensions.st_makepoint(at_lng, at_lat), 4326)::extensions.geography
         )
  from public.places p
  where extensions.st_dwithin(
          p.location,
          extensions.st_setsrid(extensions.st_makepoint(at_lng, at_lat), 4326)::extensions.geography,
          radius_m
        )
  order by 2
  limit 20;
$$;

revoke execute on function public.nearby_places(double precision, double precision, integer) from public, anon;
grant execute on function public.nearby_places(double precision, double precision, integer) to authenticated;


-- ════════════════════════════════════════════════════════════════════════════
-- schemas/04_visits.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Visits: one person's experience of one place — rating, the required tip,
-- review text, photos, tags. Many visits per place (yours, friends',
-- revisits). Kept separate from `places` on purpose.

create table public.visits (
  id          uuid primary key default gen_random_uuid(),
  place_id    uuid not null references public.places (id) on delete cascade,
  author_id   uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  visited_on  date not null default current_date,
  status      public.visit_status not null default 'visited',
  -- 0 means not rated (e.g. Want to go).
  rating      numeric(2, 1) not null default 0 check (rating between 0 and 5),
  -- "One thing to know" — required (PRD REV-3).
  tip         text not null check (char_length(tip) between 1 and 90),
  body        text not null default '' check (char_length(body) <= 280),
  -- Free-form "with" labels: friend first names, "family", "solo".
  companions  text[] not null default '{}',
  tags        text[] not null default '{}',
  budget      text check (budget in ('₹', '₹₹', '₹₹₹', '₹₹₹₹')),
  -- Hidden pins (home, workplace) are visible only to the author (PRD PRV-2).
  is_hidden   boolean not null default false,
  verified    boolean not null default false,
  verified_by text check (verified_by in ('gps', 'exif')),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  check (verified = (verified_by is not null))
);

comment on table public.visits is 'A person''s visit to a place: status, rating, tip, review.';

create index visits_author_idx on public.visits (author_id, visited_on desc);
create index visits_place_idx on public.visits (place_id);
create index visits_created_idx on public.visits (created_at desc);

create trigger visits_set_updated_at
  before update on public.visits
  for each row execute function private.set_updated_at();

create table public.visit_photos (
  id           uuid primary key default gen_random_uuid(),
  visit_id     uuid not null references public.visits (id) on delete cascade,
  -- Object path in the `visit-photos` bucket: {author_id}/{visit_id}/{n}.jpg
  storage_path text not null,
  position     smallint not null check (position between 0 and 4),
  created_at   timestamptz not null default now(),
  unique (visit_id, position)
);

comment on table public.visit_photos is 'Up to five photos per visit (PRD REV-5).';

-- ── Row-level security ──────────────────────────────────────────────────────

alter table public.visits enable row level security;
alter table public.visit_photos enable row level security;

create policy "Visible visits"
  on public.visits for select
  to authenticated
  using (
    author_id = (select auth.uid())
    or (not is_hidden and private.can_view_profile(author_id))
  );

create policy "Authors add their visits"
  on public.visits for insert
  to authenticated
  with check (author_id = (select auth.uid()));

create policy "Authors edit their visits"
  on public.visits for update
  to authenticated
  using (author_id = (select auth.uid()))
  with check (author_id = (select auth.uid()));

create policy "Authors delete their visits"
  on public.visits for delete
  to authenticated
  using (author_id = (select auth.uid()));

-- Photos follow their visit.
create policy "Photos of visible visits"
  on public.visit_photos for select
  to authenticated
  using (exists (select 1 from public.visits v where v.id = visit_id));

create policy "Authors manage their photos"
  on public.visit_photos for all
  to authenticated
  using (exists (select 1 from public.visits v where v.id = visit_id and v.author_id = (select auth.uid())))
  with check (exists (select 1 from public.visits v where v.id = visit_id and v.author_id = (select auth.uid())));

-- ── Grants ──────────────────────────────────────────────────────────────────

grant select, delete on public.visits to authenticated;
-- `verified` / `verified_by` are set server-side only, never by the client.
-- `id` is allowed so the app can show a new review before the server replies.
grant insert (id, place_id, visited_on, status, rating, tip, body, companions, tags, budget, is_hidden)
  on public.visits to authenticated;
grant update (visited_on, status, rating, tip, body, companions, tags, budget, is_hidden)
  on public.visits to authenticated;
grant select, insert, delete on public.visit_photos to authenticated;
grant all on public.visits, public.visit_photos to service_role;


-- ════════════════════════════════════════════════════════════════════════════
-- schemas/05_saved_places.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Saved places: one tap "Save to Want to go" from a friend's pin or the feed
-- (PRD PLC-4). Private to the person who saved.

create table public.saved_places (
  profile_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  place_id   uuid not null references public.places (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (profile_id, place_id)
);

comment on table public.saved_places is 'Places a user saved to Want to go.';

alter table public.saved_places enable row level security;

create policy "Users see their saved places"
  on public.saved_places for select
  to authenticated
  using (profile_id = (select auth.uid()));

create policy "Users save places for themselves"
  on public.saved_places for insert
  to authenticated
  with check (profile_id = (select auth.uid()));

create policy "Users unsave their places"
  on public.saved_places for delete
  to authenticated
  using (profile_id = (select auth.uid()));

grant select, delete on public.saved_places to authenticated;
grant insert (place_id) on public.saved_places to authenticated;
grant all on public.saved_places to service_role;


-- ════════════════════════════════════════════════════════════════════════════
-- schemas/06_lists.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Lists: named collections of places. Collaborative lists have several
-- members who add places and vote on them (PRD LST-1, LST-2).

create table public.lists (
  id            uuid primary key default gen_random_uuid(),
  owner_id      uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  title         text not null check (char_length(title) between 1 and 80),
  -- "planning for Jan 2027".
  planning_note text not null default '' check (char_length(planning_note) <= 80),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create table public.list_members (
  list_id    uuid not null references public.lists (id) on delete cascade,
  profile_id uuid not null references public.profiles (id) on delete cascade,
  role       public.list_role not null default 'editor',
  joined_at  timestamptz not null default now(),
  primary key (list_id, profile_id)
);

create table public.list_items (
  id         uuid primary key default gen_random_uuid(),
  list_id    uuid not null references public.lists (id) on delete cascade,
  place_id   uuid not null references public.places (id) on delete cascade,
  added_by   uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (list_id, place_id)
);

create table public.list_item_votes (
  item_id    uuid not null references public.list_items (id) on delete cascade,
  profile_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (item_id, profile_id)
);

comment on table public.lists is 'Personal and collaborative lists of places.';

create index list_members_profile_idx on public.list_members (profile_id);
create index list_items_list_idx on public.list_items (list_id, created_at desc);

create trigger lists_set_updated_at
  before update on public.lists
  for each row execute function private.set_updated_at();

-- The owner is always a member.
create function private.add_list_owner()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.list_members (list_id, profile_id, role)
  values (new.id, new.owner_id, 'owner')
  on conflict do nothing;
  return new;
end;
$$;

create trigger lists_add_owner
  after insert on public.lists
  for each row execute function private.add_list_owner();

-- True when the caller is a member of the list.
create function private.is_list_member(target uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.list_members m
    where m.list_id = target and m.profile_id = (select auth.uid())
  );
$$;

revoke execute on function private.add_list_owner() from public, anon, authenticated;
revoke execute on function private.is_list_member(uuid) from public, anon;
grant execute on function private.is_list_member(uuid) to authenticated;

-- ── Row-level security ──────────────────────────────────────────────────────

alter table public.lists enable row level security;
alter table public.list_members enable row level security;
alter table public.list_items enable row level security;
alter table public.list_item_votes enable row level security;

create policy "Members see their lists"
  on public.lists for select
  to authenticated
  using (owner_id = (select auth.uid()) or private.is_list_member(id));

create policy "Users create lists they own"
  on public.lists for insert
  to authenticated
  with check (owner_id = (select auth.uid()));

create policy "Owners edit their lists"
  on public.lists for update
  to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));

create policy "Owners delete their lists"
  on public.lists for delete
  to authenticated
  using (owner_id = (select auth.uid()));

create policy "Members see who else is in the list"
  on public.list_members for select
  to authenticated
  using (private.is_list_member(list_id));

-- Owners invite friends; members can leave.
create policy "Owners add members"
  on public.list_members for insert
  to authenticated
  with check (
    exists (select 1 from public.lists l where l.id = list_id and l.owner_id = (select auth.uid()))
    and private.are_friends((select auth.uid()), profile_id)
  );

create policy "Owners remove members, members leave"
  on public.list_members for delete
  to authenticated
  using (
    profile_id = (select auth.uid())
    or exists (select 1 from public.lists l where l.id = list_id and l.owner_id = (select auth.uid()))
  );

create policy "Members see items"
  on public.list_items for select
  to authenticated
  using (private.is_list_member(list_id));

create policy "Members add items"
  on public.list_items for insert
  to authenticated
  with check (added_by = (select auth.uid()) and private.is_list_member(list_id));

create policy "Members remove items"
  on public.list_items for delete
  to authenticated
  using (private.is_list_member(list_id));

create policy "Members see votes"
  on public.list_item_votes for select
  to authenticated
  using (exists (select 1 from public.list_items i where i.id = item_id));

create policy "Members vote as themselves"
  on public.list_item_votes for insert
  to authenticated
  with check (
    profile_id = (select auth.uid())
    and exists (select 1 from public.list_items i where i.id = item_id)
  );

create policy "Members remove their vote"
  on public.list_item_votes for delete
  to authenticated
  using (profile_id = (select auth.uid()));

-- ── Grants ──────────────────────────────────────────────────────────────────

grant select, delete on public.lists to authenticated;
grant insert (title, planning_note) on public.lists to authenticated;
grant update (title, planning_note) on public.lists to authenticated;
grant select, insert, delete on public.list_members to authenticated;
grant select, delete on public.list_items to authenticated;
grant insert (list_id, place_id) on public.list_items to authenticated;
grant select, delete on public.list_item_votes to authenticated;
grant insert (item_id) on public.list_item_votes to authenticated;
grant all on public.lists, public.list_members, public.list_items, public.list_item_votes to service_role;


-- ════════════════════════════════════════════════════════════════════════════
-- schemas/07_social.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Social: "Ask for recs" posts, the pins friends reply with, and likes on
-- visits, asks and lists.

create table public.asks (
  id         uuid primary key default gen_random_uuid(),
  author_id  uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  -- Where they're going: "Shillong".
  destination text not null check (char_length(destination) between 1 and 80),
  body       text not null check (char_length(body) between 1 and 280),
  created_at timestamptz not null default now()
);

create table public.ask_replies (
  id         uuid primary key default gen_random_uuid(),
  ask_id     uuid not null references public.asks (id) on delete cascade,
  author_id  uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  place_id   uuid not null references public.places (id) on delete cascade,
  note       text not null default '' check (char_length(note) <= 140),
  created_at timestamptz not null default now(),
  unique (ask_id, author_id, place_id)
);

create table public.likes (
  profile_id   uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  subject_type public.like_subject not null,
  subject_id   uuid not null,
  created_at   timestamptz not null default now(),
  primary key (profile_id, subject_type, subject_id)
);

comment on table public.asks is 'Ask for recs: "Going to Shillong next week, suggestions?"';
comment on table public.likes is 'Likes on visits, asks and lists, shown as counts in the feed.';

create index asks_author_idx on public.asks (author_id, created_at desc);
create index ask_replies_ask_idx on public.ask_replies (ask_id);
create index likes_subject_idx on public.likes (subject_type, subject_id);

-- ── Row-level security ──────────────────────────────────────────────────────

alter table public.asks enable row level security;
alter table public.ask_replies enable row level security;
alter table public.likes enable row level security;

create policy "Asks are visible like the author's profile"
  on public.asks for select
  to authenticated
  using (private.can_view_profile(author_id));

create policy "Authors post asks"
  on public.asks for insert
  to authenticated
  with check (author_id = (select auth.uid()));

create policy "Authors delete asks"
  on public.asks for delete
  to authenticated
  using (author_id = (select auth.uid()));

create policy "Replies are visible with their ask"
  on public.ask_replies for select
  to authenticated
  using (exists (select 1 from public.asks a where a.id = ask_id));

create policy "Users reply to asks they can see"
  on public.ask_replies for insert
  to authenticated
  with check (author_id = (select auth.uid()) and exists (select 1 from public.asks a where a.id = ask_id));

create policy "Authors delete their replies"
  on public.ask_replies for delete
  to authenticated
  using (author_id = (select auth.uid()));

-- Like counts are public to signed-in users; the subject's own RLS decides
-- whether anyone can see the thing being liked.
create policy "Signed-in users see likes"
  on public.likes for select
  to authenticated
  using (true);

create policy "Users like as themselves"
  on public.likes for insert
  to authenticated
  with check (profile_id = (select auth.uid()));

create policy "Users remove their likes"
  on public.likes for delete
  to authenticated
  using (profile_id = (select auth.uid()));

-- ── Grants ──────────────────────────────────────────────────────────────────

grant select, delete on public.asks, public.ask_replies, public.likes to authenticated;
grant insert (destination, body) on public.asks to authenticated;
grant insert (ask_id, place_id, note) on public.ask_replies to authenticated;
grant insert (subject_type, subject_id) on public.likes to authenticated;
grant all on public.asks, public.ask_replies, public.likes to service_role;


-- ════════════════════════════════════════════════════════════════════════════
-- schemas/08_notifications.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Notifications: in-app activity for one recipient (PRD NTF-1, NTF-2).
-- The app writes the sentence from `kind` + `payload`, so wording can change
-- without a migration.
--
-- payload keys by kind:
--   joined         {}
--   friend_request {}
--   liked          {"place": "Neermahal", "others": 3}
--   thanks         {"place": "Hilltop Momo Stall"}
--   nudge          {"place": "Lakeside Reading Café", "minutes": 40, "place_id": "…"}
--   list_invite    {"list": "Goa trip 2027", "list_id": "…"}

create table public.notifications (
  id           uuid primary key default gen_random_uuid(),
  recipient_id uuid not null references public.profiles (id) on delete cascade,
  kind         public.notification_kind not null,
  -- Who caused it; null for system nudges.
  actor_id     uuid references public.profiles (id) on delete cascade,
  payload      jsonb not null default '{}'::jsonb,
  read_at      timestamptz,
  created_at   timestamptz not null default now()
);

create index notifications_recipient_idx on public.notifications (recipient_id, created_at desc);

-- ── Row-level security ──────────────────────────────────────────────────────

alter table public.notifications enable row level security;

create policy "Recipients read their notifications"
  on public.notifications for select
  to authenticated
  using (recipient_id = (select auth.uid()));

create policy "Recipients mark their notifications read"
  on public.notifications for update
  to authenticated
  using (recipient_id = (select auth.uid()))
  with check (recipient_id = (select auth.uid()));

-- ── Grants ──────────────────────────────────────────────────────────────────

-- Inserts come from triggers below and server-side jobs, never the client.
grant select on public.notifications to authenticated;
grant update (read_at) on public.notifications to authenticated;
grant all on public.notifications to service_role;

-- ── Triggers that create notifications ──────────────────────────────────────

create function private.notify_friend_request()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.notifications (recipient_id, kind, actor_id)
  values (new.addressee_id, 'friend_request', new.requester_id);
  return new;
end;
$$;

create trigger friendships_notify_request
  after insert on public.friendships
  for each row when (new.status = 'pending')
  execute function private.notify_friend_request();

create function private.notify_list_invite()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  list_row public.lists%rowtype;
begin
  select * into list_row from public.lists where id = new.list_id;
  if new.role = 'editor' and list_row.owner_id <> new.profile_id then
    insert into public.notifications (recipient_id, kind, actor_id, payload)
    values (new.profile_id, 'list_invite', list_row.owner_id,
            jsonb_build_object('list', list_row.title, 'list_id', list_row.id));
  end if;
  return new;
end;
$$;

create trigger list_members_notify_invite
  after insert on public.list_members
  for each row execute function private.notify_list_invite();

revoke execute on function private.notify_friend_request() from public, anon, authenticated;
revoke execute on function private.notify_list_invite() from public, anon, authenticated;


-- ════════════════════════════════════════════════════════════════════════════
-- schemas/09_feed_and_stats.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Read-side functions: the friends feed and per-person stats. Business rules
-- live here so the iPhone app, Android and the web share page get the same
-- answers.

-- ── Friends feed (PRD FEED-1) ───────────────────────────────────────────────
-- Chronological, no ranking. Three kinds of item:
--   visit — a friend logged a place
--   ask   — a friend asked for recommendations
--   list  — a friend added places to a list you're both in (grouped per day)
-- Runs as the caller, so every row still passes the tables' RLS.

create function public.get_feed(before timestamptz default now(), max_items integer default 30)
returns table (
  id          uuid,
  kind        text,
  author_id   uuid,
  verb        text,
  subject     text,
  place_id    uuid,
  category    public.place_category,
  rating      numeric,
  quote       text,
  footnote    text,
  like_count  integer,
  liked_by_me boolean,
  created_at  timestamptz
)
language sql
stable
set search_path = ''
as $$
  with friends as (
    select private.friend_ids() as id
  ),
  items as (
    -- Visits
    select v.id,
           'visit'::text as kind,
           v.author_id,
           'visited'::text as verb,
           p.name as subject,
           p.id as place_id,
           p.category,
           v.rating,
           coalesce(nullif(v.body, ''), v.tip) as quote,
           null::text as footnote,
           'visit'::public.like_subject as like_type,
           v.id as like_id,
           v.created_at
    from public.visits v
    join public.places p on p.id = v.place_id
    where v.author_id in (select id from friends)
      and v.status <> 'want_to_go'

    union all

    -- Asks
    select a.id,
           'ask',
           a.author_id,
           'is going to',
           a.destination,
           null,
           null,
           null,
           a.body,
           (select case when count(distinct r.author_id) = 0 then null
                        when count(distinct r.author_id) = 1 then '1 friend replied with pins'
                        else count(distinct r.author_id) || ' friends replied with pins' end
            from public.ask_replies r where r.ask_id = a.id),
           'ask',
           a.id,
           a.created_at
    from public.asks a
    where a.author_id in (select id from friends)

    union all

    -- List additions, one item per list, person and day
    select (array_agg(li.id order by li.created_at))[1],
           'list',
           li.added_by,
           case when count(*) = 1 then 'added a place to' else 'added ' || count(*) || ' places to' end,
           l.title,
           null,
           null,
           null,
           l.title,
           (select count(*) from public.list_items x where x.list_id = l.id) || ' places · '
             || (select count(*) from public.list_members m where m.list_id = l.id) || ' friends',
           'list',
           l.id,
           max(li.created_at)
    from public.list_items li
    join public.lists l on l.id = li.list_id
    where li.added_by in (select id from friends)
    group by l.id, l.title, li.added_by, date_trunc('day', li.created_at)
  )
  select i.id, i.kind, i.author_id, i.verb, i.subject, i.place_id, i.category, i.rating, i.quote,
         i.footnote,
         (select count(*)::integer from public.likes k
          where k.subject_type = i.like_type and k.subject_id = i.like_id),
         exists (select 1 from public.likes k
                 where k.subject_type = i.like_type and k.subject_id = i.like_id
                   and k.profile_id = (select auth.uid())),
         i.created_at
  from items i
  where i.created_at < before
  order by i.created_at desc
  limit least(greatest(max_items, 1), 100);
$$;

revoke execute on function public.get_feed(timestamptz, integer) from public, anon;
grant execute on function public.get_feed(timestamptz, integer) to authenticated;

-- ── Per-person stats ────────────────────────────────────────────────────────
-- Counts and taste match for the people the app is showing. Stats are only
-- returned for profiles the caller is allowed to see (PRD PRV-1); mutual
-- friend counts are always returned so requests can say "3 mutual friends".

create function public.profile_summaries(ids uuid[])
returns table (
  profile_id     uuid,
  places_count   integer,
  cities_count   integer,
  last_place     text,
  taste_match    integer,
  mutual_friends integer
)
language sql
stable
security definer
set search_path = ''
as $$
  with targets as (
    select distinct t.id, private.can_view_profile(t.id) as visible
    from unnest(ids[1:200]) as t(id)
  ),
  my_friends as (
    select private.friend_ids() as id
  )
  select t.id,
         case when t.visible then (
           select count(distinct v.place_id)::integer from public.visits v
           where v.author_id = t.id and v.status <> 'want_to_go'
             and (not v.is_hidden or t.id = (select auth.uid()))
         ) end,
         case when t.visible then (
           select count(distinct coalesce(p.city, p.area))::integer
           from public.visits v join public.places p on p.id = v.place_id
           where v.author_id = t.id and v.status <> 'want_to_go'
             and (not v.is_hidden or t.id = (select auth.uid()))
         ) end,
         case when t.visible then (
           select p.name from public.visits v join public.places p on p.id = v.place_id
           where v.author_id = t.id and v.status <> 'want_to_go'
             and (not v.is_hidden or t.id = (select auth.uid()))
           order by v.visited_on desc, v.created_at desc
           limit 1
         ) end,
         -- 100 when you always agree; minus 20 points per star of average gap.
         case when t.visible and t.id <> (select auth.uid()) then (
           select round(greatest(0, 100 - avg(abs(mine.rating - theirs.rating)) * 20))::integer
           from public.visits mine
           join public.visits theirs on theirs.place_id = mine.place_id
           where mine.author_id = (select auth.uid()) and mine.rating > 0
             and theirs.author_id = t.id and theirs.rating > 0 and not theirs.is_hidden
         ) end,
         (
           select count(*)::integer from public.friendships f
           where f.status = 'accepted'
             and t.id in (f.requester_id, f.addressee_id)
             and (case when f.requester_id = t.id then f.addressee_id else f.requester_id end)
                 in (select id from my_friends)
         )
  from targets t;
$$;

revoke execute on function public.profile_summaries(uuid[]) from public, anon;
grant execute on function public.profile_summaries(uuid[]) to authenticated;


-- ════════════════════════════════════════════════════════════════════════════
-- schemas/10_account.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Account-level functions: contact matching and account deletion.

-- ── Contact sync (PRD CON-2, CON-3, CON-8) ─────────────────────────────────
-- Takes the caller's contacts' numbers (E.164, e.g. +919876543210) and returns
-- only the profiles that match a verified, discoverable user. The input array
-- is never written anywhere: no table, no log. Non-users stay unknown.

create function public.match_contacts(phones text[])
returns table (profile_id uuid)
language sql
stable
security definer
set search_path = ''
as $$
  select p.id
  from public.profiles p
  join auth.users u on u.id = p.id
  where p.discoverable_by_phone
    and p.id <> (select auth.uid())
    and u.phone_confirmed_at is not null
    -- auth.users stores phones as digits only (919876543210).
    and u.phone in (
      select regexp_replace(n, '[^0-9]', '', 'g')
      from unnest(phones[1:2000]) as n
    );
$$;

revoke execute on function public.match_contacts(text[]) from public, anon;
grant execute on function public.match_contacts(text[]) to authenticated;

-- ── Delete my account (PRD PRV-4) ──────────────────────────────────────────
-- Removes the auth user; every table cascades from profiles. Photo files in
-- Storage are removed by a server-side cleanup job (not yet built).

create function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is null then
    raise exception 'Not signed in';
  end if;
  delete from auth.users where id = (select auth.uid());
end;
$$;

revoke execute on function public.delete_my_account() from public, anon;
grant execute on function public.delete_my_account() to authenticated;


-- ════════════════════════════════════════════════════════════════════════════
-- schemas/11_storage.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Storage: the private bucket for review photos.
-- Object paths: {author_id}/{visit_id}/{position}.jpg — the first folder is
-- the owner, which is what the policies check.
--
-- Note: `supabase db diff` does not track the storage schema. When this file
-- changes, copy the change into the new migration by hand.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('visit-photos', 'visit-photos', false, 5242880, array['image/jpeg', 'image/png', 'image/heic', 'image/webp'])
on conflict (id) do nothing;

create policy "Visit photos are visible like the author's profile"
  on storage.objects for select
  to authenticated
  using (
    bucket_id = 'visit-photos'
    and private.can_view_profile(((storage.foldername(name))[1])::uuid)
  );

create policy "Authors upload photos to their own folder"
  on storage.objects for insert
  to authenticated
  with check (
    bucket_id = 'visit-photos'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

create policy "Authors delete their own photos"
  on storage.objects for delete
  to authenticated
  using (
    bucket_id = 'visit-photos'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );
